namespace EnergyPriceService;

public class CalculateTaxRequest
{
    public double Amount { get; set; }
    public double TaxRatePercent { get; set; }
}

namespace EnergyPriceService;

public class CalculateTaxResponse
{
    public double Tax { get; set; }
}

app.MapPost("/api/calculate-tax", (CalculateTaxRequest request) =>
{
    var tax = BillingLogic.CalculateTax(request.Amount, request.TaxRatePercent);
    return Results.Ok(new CalculateTaxResponse { Tax = tax });
});

export async function calculateTax(body) {
  const response = await fetch('/api/calculate-tax', {
    method: 'POST',
    headers: jsonHeaders,
    body: JSON.stringify(body),
  })
  if (!response.ok) throw new Error(`calculateTax: ${response.status}`)
  return response.json()
}
